message.content:
{
  "description": "The creature is shown in side profile standing on a patch of sparse grass and dirt. It has the overall body shape, fur, head, and legs of a goat, but its back is covered by a large, domed, turtle-like shell and its shoulders, thighs, and lower leg joints are covered by smaller clusters of the same hard, polygonal, pyramidal scutes. The fur is long and shaggy, brown on the back, neck, head, and upper legs with a white underbelly and lower legs, and the shell and leg plates are brown and blackish with concentric ridged patterning.",
  "parts": [
    {
      "part": "head",
      "looks_like": "a goat head with brown shaggy fur, a lighter muzzle, dark nose, dark eyes, and a long beard of hanging hair under the chin",
      "where": "at the front end of the body on top of the neck, facing to the right"
    },
    {
      "part": "horns",
      "looks_like": "two thick, curved, ridged horns that are dark brown with horizontal rings, tapering to points and curving backward",
      "where": "on top of the head behind the forehead, one slightly in front of the other"
    },
    {
      "part": "ears",
      "looks_like": "two small, pointed, furry ears with pinkish inner surfaces, covered in brown hair",
      "where": "on the sides of the head just behind and below the horns"
    },
    {
      "part": "mane and beard",
      "looks_like": "long, shaggy, brown hair forming a thick fringe along the neck, chest, and under the jaw, with a distinct tufted beard hanging from the chin",
      "where": "along the dorsal and ventral sides of the neck and on the chin"
    },
    {
      "part": "legs",
      "looks_like": "four sturdy, furry legs that are brown on the upper portions and creamy white on the lower portions, with patches of hard polygonal scutes on the upper forelegs and hind thighs and around the joints",
      "where": "under the body, two forelegs at the front and two hind legs at the rear, supporting the body"
    },
    {
      "part": "feet",
      "looks_like": "cloven hooves that are dark brown and slightly furry at the top where they meet the leg",
      "where": "at the bottom tip of each of the four legs, in contact with the ground"
    },
    {
      "part": "tail",
      "looks_like": "a short, bushy, furry tail that is brown with white underneath and hair hanging down",
      "where": "at the rear end of the body, behind the shell and above the hind legs"
    },
    {
      "part": "shell",
      "looks_like": "a large, domed carapace made of many interlocking polygonal scutes that are brown with dark brown to black centers and raised pyramidal points, with concentric growth rings on each scute",
      "where": "covering the entire back from behind the shoulders to above the hindquarters, sitting on top of the fur"
    },
    {
      "part": "plates",
      "looks_like": "smaller clusters of the same hard, hexagonal to polygonal, pyramidal, brown and black scutes as the back shell, forming armor-like patches",
      "where": "on the outer side of each shoulder and each thigh, and as bands encircling the lower foreleg and hind leg joints near the knees and hocks"
    },
    {
      "part": "scales",
      "looks_like": "the hard, keratinous, ridged scutes that make up the shell and leg plates, each with a raised center and layered rings",
      "where": "on the back shell and on the shoulder, thigh, and lower leg plates"
    },
    {
      "part": "markings",
      "looks_like": "a large patch of creamy white fur contrasting with the surrounding brown fur",
      "where": "on the underbelly, lower chest, and inner lower legs"
    }
  ],
  "attached_objects": [],
  "animals": [
    "goat",
    "turtle"
  ],
  "separate_bodies": 1,
  "heads": 1,
  "walking_legs": 4,
  "wings": 0,
  "extra_limb_pieces": 0,
  "tails": 1
}
